import React from 'react';
import { RedditProvider } from './context/RedditContext';
import RedditCount from './components/RedditCount';
import RedditSummary from './components/RedditSummary';

const App = () => {
  const sampleVersion = 'chrome'; // Replace dynamically with actual version/product name

  return (
    <RedditProvider>
      <div className="top-bar">
        <RedditCount />
      </div>

      <div className="version-card">
        <h3>Version: Chrome</h3>
        <RedditSummary versionName={sampleVersion} />
      </div>
    </RedditProvider>
  );
};

export default App;
